const $=s=>document.querySelector(s);
export async function getAccount({beforeLogout}){
 const identityKey='courtside.activeAccount';
 async function request(path,body){const r=await fetch('/api/auth/'+path,{method:body?'POST':'GET',cache:'no-store',headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Account connection failed.');return data;}
 function form(register=false){$('#authStatus').textContent=register?'Create an account with a username and password. No email needed.':'Sign in to your games and collections.';$('#authFormArea').innerHTML=`<form id="accountForm"><label>Username<input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" pattern="[a-zA-Z0-9_]{3,24}" minlength="3" maxlength="24" required></label><label>Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="72" required></label>${register?'<p class="muted">Use 3–24 letters, numbers or underscores for your username. Password: at least 12 characters. Save it in your password manager; there is no email password reset.</p>':''}<button class="primary">${register?'Create account':'Sign in'}</button></form><button id="switchAccountForm">${register?'Already have an account? Sign in':'New here? Create account'}</button>`;$('#switchAccountForm').onclick=()=>form(!register);$('#accountForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const {user}=await request(register?'register':'login',Object.fromEntries(new FormData(e.target)));localStorage.setItem(identityKey,JSON.stringify(user));location.reload();}catch(err){$('#authStatus').textContent=err.message;e.submitter.disabled=false;}};}
 let user;try{({user}=await request('session'));}catch{try{user=JSON.parse(localStorage.getItem(identityKey));}catch{}if(!user){form();$('#authStatus').textContent='Connect to the internet to sign in. Your saved games are kept.';return null;}$('#authStatus').textContent='Offline · using this account’s local backup.';}
 if(!user){localStorage.removeItem(identityKey);form();return null;}
 localStorage.setItem(identityKey,JSON.stringify(user));$('#authScreen').hidden=true;$('#accountName').textContent=user.username;$('#signOut').hidden=false;
 $('#signOut').onclick=async()=>{const b=$('#signOut');b.disabled=true;await beforeLogout();try{await request('logout',{});localStorage.removeItem(identityKey);location.reload();}catch{b.disabled=false;alert('Connect to the internet to finish signing out. Your backup is saved on this device.');}};
 window.addEventListener('account-expired',()=>{beforeLogout();localStorage.removeItem(identityKey);location.reload();},{once:true});window.addEventListener('storage',e=>{if(e.key===identityKey&&e.newValue!==JSON.stringify(user))location.reload();});
 return user;
}
